constexpr uint8_t BUILTIN_COUNT = sizeof(BUILTIN_LINES) / sizeof(BUILTIN_LINES[0]);
constexpr uint16_t MAX_PRESET_ID = 250;

// Numeric aliases also reserve their slot; other root keys stay intact.
uint16_t presetSlot(const char* key) {
  const size_t length = strnlen(key, 4);
  if (!length || length > 3) return 0;
  uint16_t value = 0;
  for (size_t i = 0; i < length; ++i) {
    if (key[i] < '0' || key[i] > '9') return 0;
    value = value * 10 + key[i] - '0';
  }
  return value <= MAX_PRESET_ID ? value : 0;
}
